"""小院子的固定文案目录。

这里的句子都应与 xiaolei 私有仓库里的《agent 迷你小院子：文案与概率审核表》
保持一致。DeepSeek 只负责初见时的物种/外观，以及照顾后的单次反应；触发规则、
连续事件和状态语气全部来自本地目录，方便宝宝逐句审核。
"""

from __future__ import annotations

from typing import NamedTuple


class SceneLine(NamedTuple):
    """一条只在指定世界事实成立时才能展示的固定文案。"""

    text: str
    seasons: tuple[str, ...] = ()
    periods: tuple[str, ...] = ()
    weather: tuple[str, ...] = ()
    calendar_ids: tuple[str, ...] = ()


_VALID_SEASONS = frozenset({"spring", "summer", "autumn", "winter"})
_VALID_PERIODS = frozenset({"dawn", "day", "dusk", "night", "late_night"})
_VALID_WEATHER = frozenset({
    "clear", "cloudy", "rain", "snow", "fog", "windy",
    "hot", "cold", "humid", "frost", "storm",
})


def scene(
    text: str,
    *,
    seasons: tuple[str, ...] = (),
    periods: tuple[str, ...] = (),
    weather: tuple[str, ...] = (),
    calendar_ids: tuple[str, ...] = (),
) -> SceneLine:
    if not text.strip():
        raise ValueError("小院子文案不能为空")
    if set(seasons) - _VALID_SEASONS or set(periods) - _VALID_PERIODS or set(weather) - _VALID_WEATHER:
        raise ValueError(f"小院子文案标签无效：{text}")
    if any(not calendar_id.strip() for calendar_id in calendar_ids):
        raise ValueError(f"小院子文案的 calendar_ids 不能为空：{text}")
    return SceneLine(text, seasons, periods, weather, calendar_ids)


