def choose_scene(
    lines: tuple[SceneLine, ...],
    *,
    season: str,
    day_period: str,
    weather_tags: frozenset[str],
    rng,
    calendar_id: str | None = None,
) -> str:
    """只从当前季节、时段、已确认天气和日历事件（如适用）都满足的候选中抽一句。"""
    eligible = [
        line for line in lines
        if (not line.seasons or season in line.seasons)
        and (not line.periods or day_period in line.periods)
        and set(line.weather).issubset(weather_tags)
        and (not line.calendar_ids or calendar_id in line.calendar_ids)
    ]
    if not eligible:
        # 每个正式候选池都必须自带无条件兜底；没有兜底是目录错误，不能冒险
        # 退回一条可能与现场冲突的句子。
        raise ValueError("小院子文案池缺少当前上下文可用的安全候选")
    specificity = max(
        int(bool(line.seasons)) + int(bool(line.periods)) + int(bool(line.weather))
        + int(bool(line.calendar_ids))
        for line in eligible
    )
    return rng.choice([
        line.text for line in eligible
        if int(bool(line.seasons)) + int(bool(line.periods)) + int(bool(line.weather))
        + int(bool(line.calendar_ids))
        == specificity
    ])


