def scene_text_compatible(
    text: str,
    *,
    season: str,
    day_period: str,
    weather_tags: frozenset[str],
    recent_rain: bool = False,
    yard_water: str = "none",
) -> bool:
    """给旧字符串池和运行时写手结果做保守的事实闸门。"""
    if not recent_rain and any(marker in text for marker in _UNPROVABLE_PAST_WEATHER):
        return False
    for markers, allowed in _PERIOD_MARKERS:
        if any(marker in text for marker in markers) and day_period not in allowed:
            return False
    for markers, allowed in _SEASON_MARKERS:
        if any(marker in text for marker in markers) and season not in allowed:
            return False
    for markers, required in _WEATHER_MARKERS:
        if (
            any(marker in text for marker in markers)
            and not required.issubset(weather_tags)
            and not (
                required == frozenset({"rain"})
                and (recent_rain or yard_water in ("puddles", "flooded"))
            )
        ):
            return False
    return True


def compatible_texts(
    lines: tuple[str, ...],
    *,
    season: str,
    day_period: str,
    weather_tags: frozenset[str],
    recent_rain: bool = False,
) -> tuple[str, ...]:
    return tuple(
        text for text in lines
        if scene_text_compatible(
            text,
            season=season,
            day_period=day_period,
            weather_tags=weather_tags,
            recent_rain=recent_rain,
        )
    )


