def yard_water_scene_line(level: str, rain_streak_days: int = 0, *, stable_index: int = 0) -> str:
    pool = YARD_WATER_SCENE_LINES.get(level)
    if not pool:
        return ""
    base = pool[stable_index % len(pool)]
    if rain_streak_days >= 7:
        return f"这雨已经连着下了一周，{base}"
    if rain_streak_days >= 2:
        return f"雨断断续续下了{rain_streak_days}天，{base}"
    return base


