def outing_flavor_line(mode: str, position: str, yard_water: str, rng) -> str | None:
    pool = OUTING_FLAVOR_LINES.get(mode, {}).get(position)
    if not pool:
        return None
    base = rng.choice(pool)
    inserts = OUTING_YARD_INSERTS.get(yard_water, {}).get(position)
    if not inserts:
        return base
    insert = rng.choice(inserts)
    if position == "prefix":
        return base.removesuffix("——") + insert + "——"
    return base.removesuffix("。") + insert + "。"


def environment_scene_mode(
    *,
    weather_tags: frozenset[str],
    weather_status: str,
    recent_rain: bool,
    soil_wet: bool,
) -> str:
    """把已确认事实收敛成一个互不冲突的整体天气画面类别。"""
    if weather_status != "fresh":
        return "season_default"
    if weather_tags.intersection({"storm", "fog", "snow"}):
        return "unsafe"
    if "rain" in weather_tags:
        return "humid_wet" if "humid" in weather_tags else "rain"
    if recent_rain:
        return "rain_after"
    if "humid" in weather_tags and soil_wet:
        return "humid_wet"
    if {"hot", "clear"}.issubset(weather_tags):
        return "hot_clear"
    if {"cold", "clear"}.issubset(weather_tags):
        return "cold_clear"
    if "windy" in weather_tags:
        return "windy"
    if "cloudy" in weather_tags:
        return "cloudy"
    if "clear" in weather_tags:
        return "clear"
    return "neutral"


def environment_scene_line(
    *,
    weather_tags: frozenset[str],
    weather_status: str,
    day_period: str,
    season: str = "spring",
    recent_rain: bool = False,
    soil_wet: bool = False,
    stable_index: int = 0,
) -> str:
    """返回不猜测天气的本地环境句；stable_index 只由场景事实派生。"""
    mode = environment_scene_mode(
        weather_tags=weather_tags,
        weather_status=weather_status,
        recent_rain=recent_rain,
        soil_wet=soil_wet,
    )
    if mode == "season_default":
        seasonal = ENVIRONMENT_SEASON_DEFAULT_LINES.get(season, ENVIRONMENT_SEASON_DEFAULT_LINES["spring"])
        base = seasonal[stable_index % len(seasonal)]
    else:
        lines = ENVIRONMENT_SCENE_LINES[mode]
        base = lines[stable_index % len(lines)]
    period_lines = ENVIRONMENT_PERIOD_LINES.get(day_period, ENVIRONMENT_PERIOD_LINES["day"])
    return base + period_lines[(stable_index // 7) % len(period_lines)]


