def crop_environment_line(
    *,
    crop: str,
    condition: str,
    soil_state: str,
    water_source: str,
    weather_tags: frozenset[str],
    growth_trend: str,
    long_wet: bool,
    stable_index: int,
) -> str | None:
    """从已经成立的作物事实中稳定选一个环境片段；没有对应事实就不硬写。"""
    category = ""
    if condition:
        category = "weather_condition"
    elif water_source == "rain" and soil_state in ("湿润", "湿透"):
        category = "rain_watered"
    elif soil_state in ("偏干", "干燥") and {"hot", "clear"}.issubset(weather_tags):
        category = "hot_dry"
    elif long_wet and soil_state == "湿透":
        category = "long_wet"
    elif growth_trend == "fast":
        category = "growth_good"
    elif growth_trend == "slow":
        category = "growth_slow"
    elif soil_state == "合适":
        category = "moisture_ok"
    if not category:
        return None
    lines = CROP_ENVIRONMENT_FALLBACKS[category]
    return lines[stable_index % len(lines)].format(crop=crop, condition=condition or "异常")


def local_crop_candidates(facts: dict, default: str) -> tuple[str, ...]:
    """只返回与代码裁决、异常类型、风格和因果完全匹配的封闭候选。"""
    if facts.get("copy_type") == "treatment":
        outcome = str(facts.get("outcome") or "")
        condition_type = str(facts.get("condition_type") or "")
        condition_key = (
            "_none" if outcome == "healthy"
            else "_any" if outcome == "withered"
            else condition_type
        )
        lines = TREATMENT_FALLBACKS.get(outcome, {}).get(condition_key)
        if not lines:
            return (default,)
        return tuple(line.format(
            crop=str(facts.get("crop_name") or "作物"),
            action=str(facts.get("action") or "处理"),
            condition=str(facts.get("condition_name") or "异常"),
        ) for line in lines)
    if facts.get("copy_type") != "watering":
        return (default,)
    outcome = str(facts.get("outcome") or "")
    weather_status = str(
        facts.get("weather_status")
        or ("fresh" if facts.get("weather_tags") else "missing")
    )
    soil_state = str(facts.get("soil_state") or "")
    water_source = str(facts.get("water_source") or "none")
    reason = str(facts.get("watering_reason") or "")
    style = str(facts.get("style") or "physical")
    context = ""
    if (
        outcome in ("no_need", "too_wet")
        and water_source == "rain"
        and soil_state in ("湿润", "湿透")
    ):
        context = "rain_no_need"
    elif weather_status != "fresh" and outcome in ("no_need", "too_wet", "refused"):
        context = "weather_missing"
    elif (
        outcome == "watered"
        and int(facts.get("watering_count") or 0) > 1
        and reason == "hot_clear_dry"
    ):
        context = "hot_same_day_watered"
    elif outcome == "watered" and reason == "hot_clear_dry":
        context = "hot_clear_dry_watered"
    elif outcome == "watered" and reason == "hot_dry":
        context = "heat_dry_watered"
    elif outcome == "watered" and reason == "wind_dry":
        context = "wind_dry_watered"
    elif outcome == "watered" and reason == "low_humidity_dry":
        context = "low_humidity_dry_watered"

    if context:
        lines = (
            _WATERING_CONTEXT_LIGHT_COMEDY[context]
            if style == "slapstick"
            else WATERING_CONTEXT_FALLBACKS[context][:-len(_WATERING_CONTEXT_LIGHT_COMEDY[context])]
        )
    else:
        lines = (
            _WATERING_LIGHT_COMEDY.get(outcome)
            if style == "slapstick"
            else WATERING_FALLBACKS.get(outcome, ())[:-len(_WATERING_LIGHT_COMEDY.get(outcome, ()))]
        )
    crop = str(facts.get("crop_name") or "作物")
    if not lines:
        return (default,)
    return tuple(line.format(
        crop=crop,
        condition=str(facts.get("condition_name") or "异常"),
    ) for line in lines)


def local_crop_fallback(facts: dict, default: str) -> str:
    """从事实兼容候选中稳定选一句；重试不会换文案。"""
    lines = local_crop_candidates(facts, default)
    signature = "|".join(f"{key}={facts.get(key)!r}" for key in sorted(facts))
    return lines[sum(ord(char) for char in signature) % len(lines)]


