            "它突然从花丛蹿出，围着我撒欢，扑得落叶四处飞散。",
            "它跑来将前爪搭上我膝盖，耳朵后抿，喘息着飞快摇尾。",
            "它在院中追自己尾巴疯转数圈，然后冲我短促地轻叫两声。",
            "它叼着一截树枝跑近，搁在我脚边，后退两步歪头看我。",
            "它从墙角弹出身子，就地打了个滚，亮出肚皮朝我扭动。",
            "本来在刨土的它甩下坑跑过来，把凉凉的鼻子塞进我手心。",
            "它沿着篱笆来回冲刺，每趟都扭头看我，像在邀我追逐。",
            "它跳起来够我手，落地后立刻换方向再跳，丝毫没有停歇。",
