            "它在砖缝间嗅了嗅，耳朵一直朝向我这边转着，随时准备弹开的样子。",
            "那双眼睛在暮色里亮晶晶的，隔了很久才缓缓眨一下，然后继续安静地注视着我。",
            "我故意放轻脚步，它却还是察觉了，后腿悄悄往后挪了半寸，却没有立刻跑开。",
