def crop_care_pool(crop_id: str, action: str) -> tuple[str, ...]:
    """返回夏季品种专属的照料成品句；旧作物没有池时继续走原兜底。"""
    traits = CROP_CARE_TRAITS.get(crop_id)
    templates = CROP_CARE_TEXT.get(action)
    if traits is None or templates is None:
        return ()
    return tuple(template.format(**traits) for template in templates)


