# 第七版阶段D：欠佳收获通用池。内涝浸泡满24h或异常拖到damaged时打上的
# "poor"标记（第六节），收获时走这批句子，不查作物专属池（专属池都是夸
# 品相的），也不触发下面的15%彩蛋。基调是心疼但不受难，禁夸品相词
# （水灵/饱满/脆生/新鲜/肥美/圆润/笔直一类），具体事实由"结果"行补充。
# 第七版阶段E：poor 现在有两个来源（内涝浸泡、异常拖到damaged），plot 上
# 只有一个不可逆的布尔标记、没有留存"是哪一种"的事实字段，因此这批句子
# 一律写成不归因的中性描写（蔫、没精神、品相一般），不再点名"泡雨/积水/
# 雨水太多"——那样会在异常导致的欠佳收获里编造一个没发生过的內涝事实。
