    "{name}的品相差了点，边角有点发软，挑挑拣拣还是收进了篮子。",
    "收下来的{name}看着有点委屈，将就着用吧。",
    "这茬{name}长得不算体面，颜色也淡了些，但份量照样收进篮子。",
