# 阶段 D：动物对现实天气的本地基础池骨架。这里的每一句都省略主语，写成
# 承接同一只动物的延续小句——初见/回访/照顾反应会直接接在已有句子后面，
# 痕迹场景会在前面补上名字。阶段 E 会用 DeepSeek 把每格扩充到至少 6 条，
# 这里只保证每种物种 × 模式都有安全候选，不会出现空池。
#
# 两轮复审发现三类会踩事实的坑，这里的措辞刻意避开：
# ① 一律不写具体地点（院门/信箱/屋檐/墙根/墙角/门口/水碗……），因为这些
#   小句是接在已有句子后面的，而已有句子（初见/回访/照顾）经常已经带着
#   ``entry["spot"]`` 这个真实位置；如果小句自己又写了另一个地点（哪怕是
#   “水碗边”这种不在 SPOTS 常量里、但一样具体的地方），两句话就会互相
#   矛盾（“院门旁……缩到屋檐下/水碗边”）。改成只写姿态和动作，不点名
#   具体在哪。
# ② “陪玩”这个动作本身就在描述持续的主动跑动，不能直接接一句“懒得动”
#   的通用天气小句——那会变成“追着你来回跑了好几趟→(马上)趴下不想动”
#   的动作矛盾。陪玩单独用下面的 ``ANIMAL_WEATHER_PLAY_LINES``，措辞本身
#   写成承接“刚才还在动”的转折句，且不点名具体玩具或前置动作（不写
#   “树枝”“纸团”之类），这样不管陪玩基础反应池当次用的是什么道具，
#   承接句都不会说错。其余动作（初见/回访/回归/投喂/摸摸/痕迹）仍用这里
#   的通用池。
# ③ ``sheltering`` 可能由雨、雷暴或纯粹的危险强风三种原因中的任意一种触发
#   （见 ``garden_weather.animal_weather_mode``），但两个池子曾经只写了雨天
#   意象（湿爪子、雨幕、雨点、雷声）——晴天强风时也会用到同一份候选，说
#   “舔被打湿的爪子”就成了事实错误。``sheltering`` 格子里不写雨/雷/水/湿/
#   潮这类只在下雨或打雷时才成立的词，只写“警觉、躲避、贴地”这类三种
#   触发原因都说得通的姿态。
