def _expand_animal_weather_pool(
    pool: dict[str, dict[str, tuple[str, ...]]],
    expansions: dict[str, dict[str, tuple[str, ...]]],
) -> None:
    """阶段 E 按物种补足候选；补句不共用泛化模板，也不点具体地点。"""
    for category, modes in pool.items():
        for mode, lines in tuple(modes.items()):
            extras = expansions.get(category, {}).get(mode, ())
            modes[mode] = tuple(lines) + tuple(extras[:max(0, 6 - len(lines))])


_expand_animal_weather_pool(ANIMAL_WEATHER_LINES, _ANIMAL_WEATHER_EXPANSIONS)
_expand_animal_weather_pool(ANIMAL_WEATHER_PLAY_LINES, _ANIMAL_WEATHER_PLAY_EXPANSIONS)


def _validate_animal_weather_lines() -> None:
    """模块导入时的一次性骨架校验：每个物种 × 模式格子都不能是空池，
    不能出现会跟真实 spot 冲突的具体地点词，sheltering 格子也不能暗示
    只有下雨/打雷才成立的具体避险原因。"""
    for pool_name, pool in (
        ("ANIMAL_WEATHER_LINES", ANIMAL_WEATHER_LINES),
        ("ANIMAL_WEATHER_PLAY_LINES", ANIMAL_WEATHER_PLAY_LINES),
    ):
        required_modes = (
            _ANIMAL_WEATHER_MODES_REQUIRING_CONTENT
            if pool_name == "ANIMAL_WEATHER_LINES"
            else _ANIMAL_WEATHER_PLAY_MODES_REQUIRING_CONTENT
        )
        categories = (
            _ANIMAL_WEATHER_GENERIC_CATEGORIES
            if pool_name == "ANIMAL_WEATHER_LINES"
            else ANIMAL_CATEGORIES
        )
        for category in categories:
            for mode in required_modes:
                lines = pool.get(category, {}).get(mode)
                if not lines or len(lines) < 6:
                    raise ValueError(f"小院子动物天气文案缺少 {pool_name}.{category}×{mode} 的候选")
                for line in lines:
                    if any(word in line for word in _ANIMAL_WEATHER_LOCATION_WORDS):
                        raise ValueError(
                            f"{pool_name}.{category}×{mode} 的候选写了具体地点，会跟真实 spot 冲突：{line}"
                        )
                    if mode == "sheltering" and any(word in line for word in _SHELTERING_CAUSE_WORDS):
                        raise ValueError(
                            f"{pool_name}.{category}×{mode} 的候选暗示了雨/雷/水才成立的避险原因，"
                            f"会跟纯强风触发的场景冲突：{line}"
                        )


_validate_animal_weather_lines()


_STAGE_E_BLOCKED_WORDS = (
    "主人", "人工智能", "ai", "模型", "程序", "代码", "游戏", "指令", "数据", "结果：",
)


def _validate_stage_e_fallback_pools() -> None:
    """把覆盖数量、占位符和沉浸禁词变成导入期约束，避免只靠测试记得查。"""
    for name, pools, minimum in (
        ("WATERING_FALLBACKS", WATERING_FALLBACKS, 8),
        ("WATERING_CONTEXT_FALLBACKS", WATERING_CONTEXT_FALLBACKS, 8),
        ("CROP_ENVIRONMENT_FALLBACKS", CROP_ENVIRONMENT_FALLBACKS, 6),
    ):
        for category, lines in pools.items():
            if len(lines) < minimum or len(set(lines)) != len(lines):
                raise ValueError(f"{name}.{category} 的本地候选数量或唯一性不足")
            for line in lines:
                lowered = line.lower()
                if any(word in lowered for word in _STAGE_E_BLOCKED_WORDS):
                    raise ValueError(f"{name}.{category} 含沉浸禁词：{line}")
                try:
                    rendered = line.format(crop="小番茄", action="除虫", condition="虫害")
                except (KeyError, ValueError) as exc:
                    raise ValueError(f"{name}.{category} 的占位符无效：{line}") from exc
                if "{" in rendered or "}" in rendered or len(rendered) > 140:
                    raise ValueError(f"{name}.{category} 的本地候选长度或占位符无效：{line}")

    for outcome, condition_pools in TREATMENT_FALLBACKS.items():
        for condition_type, lines in condition_pools.items():
            if len(lines) < 6 or len(set(lines)) != len(lines):
                raise ValueError(
                    f"TREATMENT_FALLBACKS.{outcome}.{condition_type} 的本地候选数量或唯一性不足"
                )
            for line in lines:
                lowered = line.lower()
                if any(word in lowered for word in _STAGE_E_BLOCKED_WORDS):
                    raise ValueError(
                        f"TREATMENT_FALLBACKS.{outcome}.{condition_type} 含沉浸禁词：{line}"
                    )
                rendered = line.format(crop="小番茄", action="除虫", condition="虫害")
                if "{" in rendered or "}" in rendered or len(rendered) > 140:
                    raise ValueError(
                        f"TREATMENT_FALLBACKS.{outcome}.{condition_type} 的占位符无效：{line}"
                    )

    required_environment_modes = {
        "clear", "hot_clear", "cloudy", "rain", "rain_after",
        "humid_wet", "windy", "cold_clear", "unsafe", "neutral",
    }
    if set(ENVIRONMENT_SCENE_LINES) != required_environment_modes:
        raise ValueError("小院子整体天气本地池模式不完整")
    for mode, lines in ENVIRONMENT_SCENE_LINES.items():
        if len(lines) < 4 or len(set(lines)) != len(lines):
            raise ValueError(f"小院子整体天气 {mode} 候选不足")
        if any(
            word in line.lower()
            for line in lines
            for word in _STAGE_E_BLOCKED_WORDS
        ):
            raise ValueError(f"小院子整体天气 {mode} 含沉浸禁词")
    for period in ("dawn", "day", "dusk", "night"):
        lines = ENVIRONMENT_PERIOD_LINES.get(period, ())
        if len(lines) < 4 or len(set(lines)) != len(lines):
            raise ValueError(f"小院子整体天气缺少 {period} 时段候选")
    for season in _VALID_SEASONS:
        lines = ENVIRONMENT_SEASON_DEFAULT_LINES.get(season, ())
        if len(lines) < 4 or len(set(lines)) != len(lines):
            raise ValueError(f"小院子缺少 {season} 无天气候选")
    if set(YARD_WATER_SCENE_LINES) != {"puddles", "flooded"}:
        raise ValueError("小院子院级积水本地池档位不完整")
    for level, lines in YARD_WATER_SCENE_LINES.items():
        if len(lines) < 6 or len(set(lines)) != len(lines):
            raise ValueError(f"小院子院级积水 {level} 候选不足")
    if set(YARD_WATER_EVENT_TEXT) != {"entered", "exited"}:
        raise ValueError("小院子内涝事件文案类型不完整")
    for transition, lines in YARD_WATER_EVENT_TEXT.items():
        if (
            len(lines) < 6
            or len(set(lines)) != len(lines)
            or any(
                len(line) > 90
                or any(word in line.lower() for word in _STAGE_E_BLOCKED_WORDS)
                for line in lines
            )
        ):
            raise ValueError(f"小院子内涝事件 {transition} 候选不安全")

    if set(FLOOD_DAMAGE_EVENT_TEXT) != {"quality", "rot"}:
        raise ValueError("小院子内涝惩罚事件文案类型不完整")
    for stage, lines in FLOOD_DAMAGE_EVENT_TEXT.items():
        required_marker = "「排水」" if stage == "quality" else "「清理」"
        if (
            len(lines) < 6
            or len(set(lines)) != len(lines)
            or any(
                len(line) > 90
                or required_marker not in line
                or any(word in line.lower() for word in _STAGE_E_BLOCKED_WORDS)
                for line in lines
            )
        ):
            raise ValueError(f"小院子内涝惩罚事件 {stage} 候选不安全")

    required_outing_modes = {
        "typhoon", "storm_rain", "windy_rain", "rain",
        "light_rain", "snow", "gale",
    }
    if set(OUTING_FLAVOR_LINES) != required_outing_modes:
        raise ValueError("小院子出门天气本地池档位不完整")
    for mode, pools in OUTING_FLAVOR_LINES.items():
        if set(pools) != {"prefix", "aftermath"}:
            raise ValueError(f"小院子出门天气 {mode} 位置不完整")
        for position, lines in pools.items():
            if len(lines) < 6 or len(set(lines)) != len(lines):
                raise ValueError(f"小院子出门天气 {mode}.{position} 候选不足")
            ending = "——" if position == "prefix" else "。"
            if any(
                not line.endswith(ending)
                or len(line) > 90
                or any(word in line.lower() for word in _STAGE_E_BLOCKED_WORDS)
                for line in lines
            ):
                raise ValueError(f"小院子出门天气 {mode}.{position} 候选不安全")
    wet_markers = ("湿", "水", "淋", "雨")
    for mode in ("typhoon", "storm_rain"):
        if any(not any(marker in line for marker in wet_markers) for line in OUTING_FLAVOR_LINES[mode]["aftermath"]):
            raise ValueError(f"小院子出门天气 {mode} 余韵缺少湿水事实")
    if set(OUTING_YARD_INSERTS) != {"puddles", "flooded"}:
        raise ValueError("小院子出门积水插句档位不完整")
    for level, pools in OUTING_YARD_INSERTS.items():
        if set(pools) != {"prefix", "aftermath"}:
            raise ValueError(f"小院子出门积水 {level} 位置不完整")
        for position, lines in pools.items():
            if len(lines) < 6 or len(set(lines)) != len(lines):
                raise ValueError(f"小院子出门积水 {level}.{position} 候选不足")
            if any(
                len(line) > 70
                or any(word in line.lower() for word in _STAGE_E_BLOCKED_WORDS)
                for line in lines
            ):
                raise ValueError(f"小院子出门积水 {level}.{position} 候选不安全")

    drain_lines = GARDEN_ACTION_TEXT.get("drain", ())
    if len(drain_lines) < 8 or len(set(drain_lines)) != len(drain_lines):
        raise ValueError("小院子排水动作候选数量或唯一性不足")
    for line in drain_lines:
        if len(line) > 90 or any(word in line.lower() for word in _STAGE_E_BLOCKED_WORDS):
            raise ValueError(f"小院子排水动作候选不安全：{line}")
        try:
            rendered = line.format()
        except (KeyError, ValueError) as exc:
            raise ValueError(f"小院子排水动作候选占位符无效：{line}") from exc
        if "{" in rendered or "}" in rendered:
            raise ValueError(f"小院子排水动作候选占位符无效：{line}")

    for pool_name, pool, modes in (
        ("ANIMAL_WEATHER_LINES", ANIMAL_WEATHER_LINES, _ANIMAL_WEATHER_MODES_REQUIRING_CONTENT),
        ("ANIMAL_WEATHER_PLAY_LINES", ANIMAL_WEATHER_PLAY_LINES, _ANIMAL_WEATHER_PLAY_MODES_REQUIRING_CONTENT),
    ):
        categories = (
            _ANIMAL_WEATHER_GENERIC_CATEGORIES
            if pool_name == "ANIMAL_WEATHER_LINES"
            else ANIMAL_CATEGORIES
        )
        for category in categories:
            for mode in modes:
                lines = pool[category][mode]
                if len(lines) < 6 or len(set(lines)) != len(lines):
                    raise ValueError(f"{pool_name}.{category}×{mode} 的候选数量或唯一性不足")
                for line in lines:
                    if len(line) > 90 or any(word in line.lower() for word in _STAGE_E_BLOCKED_WORDS):
                        raise ValueError(f"{pool_name}.{category}×{mode} 的候选不安全：{line}")


_validate_stage_e_fallback_pools()

